/// <summary>
/// Custom lookup method for ItemId.
/// </summary>
/// <param name = "_formControl"></param>
/// <param name = "_filterStr"></param>
public void lookup(FormControl _formControl, str _filterStr)
{
    Query                   query;
    QueryBuildDataSource   qbdsSalesLine;
    QueryBuildDataSource   qbdsSalesTable;
    QueryBuildRange        qbrReturnItemNum;
    SysTableLookup         sysTableLookup;

    // Create a new query
    query = new Query();

    // Root should be SalesLine since lookup is on SalesLine.ItemId
    qbdsSalesLine = query.addDataSource(tableNum(SalesLine));

    // Join SalesTable to SalesLine
    qbdsSalesTable = qbdsSalesLine.addDataSource(tableNum(SalesTable));
    qbdsSalesTable.relations(true);
    qbdsSalesTable.joinMode(JoinMode::InnerJoin);

    // Add range on ReturnItemNum field from SalesTable
    qbrReturnItemNum = qbdsSalesTable.addRange(fieldNum(SalesTable, ReturnItemNum));
    qbrReturnItemNum.value(SysQuery::value(METDutyCreditTable.RMANumber));

    // Setup SysTableLookup on SalesLine and control
    sysTableLookup = SysTableLookup::newParameters(tableNum(SalesLine), _formControl);
    sysTableLookup.addLookupfield(fieldNum(SalesLine, ItemId)); // You can add more fields as needed

    // Assign the query to the lookup
    sysTableLookup.parmQuery(query);

    // Execute the lookup
    sysTableLookup.performFormLookup();
}

/// <summary>
/// Custom lookup method for SalesTable.ReturnItemNum where ReturnItemNum is not null.
/// </summary>
/// <param name = "_formControl"></param>
/// <param name = "_filterStr"></param>
public void lookup(FormControl _formControl, str _filterStr)
{
    Query                   query;
    QueryBuildDataSource    qbdsSalesTable;
    QueryBuildRange         qbrReturnItemNum;
    SysTableLookup          sysTableLookup;

    // Initialize the query
    query = new Query();

    // Add SalesTable as the data source
    qbdsSalesTable = query.addDataSource(tableNum(SalesTable));

    sysTableLookup = SysTableLookup::newParameters(tableNum(SalesTable), _formControl);

    qbrReturnItemNum = qbdsSalesTable.addRange(fieldNum(SalesTable, ReturnItemNum)); 
    qbrReturnItemNum.value(SysQuery::valueNotEmptyString()); // Filters for non-empty strings

    // Display SalesId, make it the primary sort field
    sysTableLookup.addLookupfield(fieldNum(SalesTable, ReturnItemNum)); // Display ReturnItemNum 
    sysTableLookup.addLookupfield(fieldNum(SalesTable, CustAccount)); // Display Customer Account
    sysTableLookup.addLookupfield(fieldNum(SalesTable, SalesName)); // Display Sales Name

    // Apply the constructed query to the lookup
    sysTableLookup.parmQuery(query);

    // Perform the lookup
    sysTableLookup.performFormLookup();
}

/// <summary>
/// Custom lookup method for siteId.
/// </summary>
/// <param name = "_formControl"></param>
/// <param name = "_filterStr"></param>
public void lookup(FormControl _formControl, str _filterStr)
{
    Query                   query;
    QueryBuildDataSource    qbdsSalesLine;
    QueryBuildDataSource    qbdsInventDim;
    QueryBuildRange         qbrReturnItemNum;
    SysTableLookup          sysTableLookup;

    query = new Query();

    // Root should be InventDim as a related data source
    qbdsInventDim = query.addDataSource(tableNum(InventDim));

    qbdsSalesLine = qbdsInventDim.addDataSource(tableNum(SalesLine));

    qbdsSalesLine.relations(true);
    qbdsSalesLine.joinMode(JoinMode::InnerJoin);

    // Apply range/filter on ReturnItemNum from SalesTable (same as in your original code)
    qbrReturnItemNum = qbdsSalesLine.addRange(fieldNum(SalesLine, SalesId));
    qbrReturnItemNum.value(SysQuery::value(SalesTable::findReturnItemNum(METDutyCreditTable.RMANumber).SalesId));

    // Setup SysTableLookup for SalesLine control
    sysTableLookup = SysTableLookup::newParameters(tableNum(InventDim), _formControl);

    // Add InventSiteId (from InventDim) to the lookup
    sysTableLookup.addLookupfield(fieldNum(InventDim, InventSiteId));

    // Apply query to SysTableLookup
    sysTableLookup.parmQuery(query);

    // Perform the lookup
    sysTableLookup.performFormLookup();
}
